<script setup>
import {ref,computed,watch,onUnmounted} from 'vue';
import {api,scope,state,company,can,useResource,changed,notify,ask,captureContext,contextMatches} from '../lib/workspace';
import BaseModal from './BaseModal.vue';
import DateInput from './DateInput.vue';
const props=defineProps({mode:{type:String,default:'catalogs'},initialKind:{type:String,default:'cfop'}});
const kind=ref(props.initialKind),query=ref(''),page=ref(1),modal=ref(''),form=ref({}),preview=ref(null),busy=ref(false),error=ref(''),versions=ref([]);
const admin=computed(()=>state.session?.user?.role==='admin');
const segmentLabels={commerce:'Comércio',industry:'Indústria',services:'Serviços',other:'Outro'};
const regimeLabels={simples_nacional:'Simples Nacional',lucro_presumido:'Lucro Presumido',lucro_real:'Lucro Real',outros:'Outros'};
const owner=Symbol('fiscal-library');let context=null,baseline='',sequence=0;
const routine=computed(()=>props.mode==='catalogs'?'fiscal.masters':'fiscal.parameters');
const {data,loading,error:loadError,reload}=useResource(async()=>{
 if(!state.companyId||!can(routine.value))return {rows:[],total:0,starters:[]};
 if(props.mode==='catalogs')return api(scope(`/global-fiscal-catalogs?${new URLSearchParams({kind:kind.value,search:query.value,page:String(page.value)})}`));
 const cid=state.companyId;const [library,imports]=await Promise.all([api(scope('/fiscal-patterns',cid)),api(scope('/fiscal-patterns/imports',cid))]);return {...library,imports};
},{rows:[],total:0,starters:[]});
const visible=computed(()=>props.mode==='catalogs'?data.value.rows:data.value.rows.filter(r=>`${r.code} ${r.name} ${regimeLabels[r.regime]} ${segmentLabels[r.segment]}`.toLocaleLowerCase().includes(query.value.toLocaleLowerCase())));
watch([kind,query],()=>{page.value=1;reload()});watch(page,reload);
watch(()=>JSON.stringify(form.value),()=>{preview.value=null});
const blankRule=()=>({name:'',tax:'icms',rate:'',direction:'both',cfop:'',ncm:'',state:'',municipality:'',source:''});
function open(type,row){if(state.editor||busy.value)return;context=captureContext();sequence++;error.value='';preview.value=null;versions.value=[];modal.value=type;
 form.value=JSON.parse(JSON.stringify(row|| (type==='catalog'?{kind:kind.value,code:'',description:'',source:'',direction:'both',rates_declared:[],service_system:'lc116',jurisdiction:'BR',active:true,valid_from:'',valid_to:''}:{code:'',name:'',description:'',source:'',regime:company.value?.regime||'outros',segment:'',activity:'',cnae_prefix:'',valid_from:'',valid_to:'',active:true,rules:[blankRule()]})));
 form.value.reason='';form.value.rates_text=(form.value.rates_declared||[]).join('; ');
 if(type==='apply'){form.value={pattern_id:row.id,version:row.version,name:row.name,pattern_segment:row.segment,segment:'',pattern_activity:row.activity||'',activity_confirmed:'',cnae_prefix:row.cnae_prefix||'',valid_from:row.valid_from||state.period+'-01',valid_to:row.valid_to||'',reason:'',responsible:''};}
 baseline=JSON.stringify(form.value);state.editor={owner,name:'Biblioteca fiscal',companyId:context.companyId};}
async function close(force=false){if(busy.value&&!force)return;if(!force&&JSON.stringify(form.value)!==baseline&&!await ask({title:'Descartar alterações?',message:'As alterações desta janela ainda não foram salvas.',confirmLabel:'Descartar'}))return;sequence++;modal.value='';preview.value=null;if(state.editor?.owner===owner)state.editor=null;}
onUnmounted(()=>{sequence++;if(state.editor?.owner===owner)state.editor=null});
function starter(event){const row=data.value.starters.find(r=>r.code===event.target.value);if(row){form.value={...JSON.parse(JSON.stringify(row)),active:true,reason:''};}}
function derive(row){open('pattern',{...JSON.parse(JSON.stringify(row)),id:undefined,version:undefined,derived_from:undefined,code:row.code+'-derivado',name:row.name+' · derivado',base_pattern_id:row.id,base_version:row.version});}
async function save(){if(busy.value||!contextMatches(context))return;busy.value=true;error.value='';const n=sequence;try{const payload=JSON.parse(JSON.stringify(form.value));let path;
 if(modal.value==='catalog'){payload.rates_declared=payload.rates_text.trim()?payload.rates_text.split(/[;\s]+/).filter(Boolean).map(r=>r.replace(',','.')):[];delete payload.rates_text;path='/global-fiscal-catalogs';}
 else{payload.rules=payload.rules.map(r=>({...r,rate:r.rate===null||r.rate===''?null:String(r.rate).replace(',','.')}));path='/fiscal-patterns';}
 if(payload.id){delete payload.base_pattern_id;delete payload.base_version;}
 await api(scope(path+(payload.id?'/'+payload.id:''),context.companyId),{method:payload.id?'PUT':'POST',body:payload,context});
 if(n!==sequence||!contextMatches(context))return;notify('Biblioteca global salva. Cópias das empresas permanecem preservadas.');await close(true);changed();await reload();
 }catch(e){if(n===sequence)error.value=e.message}finally{busy.value=false}}
async function prepare(){if(busy.value||!contextMatches(context))return;busy.value=true;error.value='';const n=sequence;try{const result=await api(scope(`/fiscal-patterns/${form.value.pattern_id}/preview`,context.companyId),{method:'POST',body:form.value,context});if(n===sequence&&contextMatches(context))preview.value=result;}catch(e){if(n===sequence)error.value=e.message}finally{busy.value=false}}
async function apply(){if(!preview.value||busy.value||!contextMatches(context))return;busy.value=true;error.value='';const n=sequence;try{const result=await api(scope(`/fiscal-patterns/${form.value.pattern_id}/apply`,context.companyId),{method:'POST',body:{...form.value,preview_hash:preview.value.preview_hash},context});if(n!==sequence||!contextMatches(context))return;notify(result.duplicate?'Este padrão já foi importado neste intervalo.':`${result.rule_ids.length} regras copiadas como rascunhos inativos. Selecione Inativas em Regras e vigência para ajustar e conferir.`);await close(true);changed();await reload();}catch(e){if(n===sequence)error.value=e.message}finally{busy.value=false}}
async function history(row){open('history',row);if(modal.value!=='history')return;busy.value=true;const n=sequence;try{const result=await api(scope(`/${props.mode==='catalogs'?'global-fiscal-catalogs':'fiscal-patterns'}/${row.id}/versions`,context.companyId));if(n===sequence&&contextMatches(context))versions.value=result;}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><details class="panel fiscal-library" v-if="can(routine)"><summary>{{mode==='catalogs'?'Tabelas fiscais globais · CFOP e serviços':'Biblioteca global de padrões fiscais'}} <small>Compartilhada entre empresas</small></summary>
<p class="message info">{{mode==='catalogs'?'Alíquotas são informativas, sem associação automática a tributo, crédito ou cálculo. A origem não informou sua vigência.':'Padrões são propostas do escritório. A importação exige regime, segmento e vigência confirmados e gera regras inativas para ajuste e conferência na empresa.'}}</p>
<p v-if="loadError" class="message error" role="alert">{{loadError}}</p>
<div class="table-toolbar"><label v-if="mode==='catalogs'">Tabela<select v-model="kind"><option value="cfop">CFOP</option><option value="service">Códigos de serviço</option></select></label><input v-model="query" aria-label="Pesquisar biblioteca fiscal global" placeholder="Pesquisar código, descrição ou padrão"/><button v-if="admin&&(mode==='patterns'||kind==='service')" class="button primary" :disabled="busy" @click="open(mode==='catalogs'?'catalog':'pattern')">{{mode==='catalogs'?'Novo código de serviço global':'Publicar padrão global'}}</button></div>
<div class="table-scroll"><table :aria-label="mode==='catalogs'?'Tabela fiscal global':'Padrões fiscais globais'"><thead><tr><th>Código</th><th>{{mode==='catalogs'?'Descrição / referência':'Padrão / enquadramento'}}</th><th>{{mode==='catalogs'?'Alíquotas informativas':'Vigência proposta'}}</th><th>Ações</th></tr></thead><tbody><tr v-for="row in visible" :key="row.id"><td>{{row.code}}<small>v{{row.version}} · {{row.active?'Ativo':'Inativo'}}</small></td><td><template v-if="mode==='catalogs'">{{row.description}}<small v-if="row.service_system">{{row.service_system}} · {{row.jurisdiction}}</small></template><template v-else>{{row.name}}<small>{{regimeLabels[row.regime]}} · {{segmentLabels[row.segment]}} · {{row.activity||'Atividade não especificada'}} · CNAE {{row.cnae_prefix||'sem filtro'}} · {{row.rules.length}} regras</small></template></td><td>{{mode==='catalogs'?(row.rates_declared.length?row.rates_declared.join(' · ')+'%':'Não informadas'):(row.valid_from||'Definir na empresa')+(row.valid_to?' até '+row.valid_to:'')}}</td><td><div class="actions"><button v-if="admin" class="button small" :disabled="busy" @click="open(mode==='catalogs'?'catalog':'pattern',row)">Editar global</button><button v-if="admin&&mode==='patterns'" class="button small" :disabled="busy" @click="derive(row)">Derivar global</button><button class="button small" :disabled="busy" @click="history(row)">Histórico</button><button v-if="mode==='patterns'&&row.active&&can('fiscal.parameters','create')" class="button small" :disabled="busy" @click="open('apply',row)">Importar na empresa</button></div></td></tr></tbody></table></div>
<p v-if="!visible.length&&!loading">{{mode==='patterns'?'Nenhum padrão publicado. O administrador pode usar uma estrutura inicial, informar as regras e publicar para importação pelas empresas.':'Nenhum registro nesta tabela ou pesquisa. Serviços precisam de tabela e jurisdição explícitas.'}}</p>
<footer v-if="mode==='catalogs'" class="table-footer"><span>{{data.total}} registros · página {{page}}</span><div class="actions"><button class="button small" :disabled="page===1||loading" @click="page--">Anterior</button><button class="button small" :disabled="page*50>=data.total||loading" @click="page++">Próxima</button></div></footer>
<details v-if="mode==='patterns'&&data.imports?.length" class="panel fiscal-rule"><summary>Cópias nesta empresa e condições de origem</summary><p>Atividade e CNAE são conferidos na importação. Não são condições automáticas de cálculo das cópias. Revise as regras antes de selecioná-las na pré-apuração, principalmente após alterar o cadastro da empresa.</p><article v-for="entry in data.imports" :key="entry.id" class="panel fiscal-rule"><strong>{{entry.snapshot.name}} · origem v{{entry.pattern_version}}</strong><p>{{segmentLabels[entry.snapshot.segment]}} · {{entry.snapshot.activity_confirmed||'Atividade não especificada'}} · CNAE na importação: {{entry.snapshot.company_cnae||'não informado'}} · filtro da origem: {{entry.snapshot.cnae_prefix||'sem filtro'}}.</p><p>Regras iniciais: {{entry.rule_ids.join(', ')}} · responsável: {{entry.snapshot.responsible}}. Edições posteriores permanecem no histórico de versões das regras.</p><p v-for="warning in entry.warnings" :key="warning.code" class="message warning">{{warning.reason}}</p></article></details>
<BaseModal v-if="modal" :wide="modal==='pattern'" :title="modal==='apply'?'Importar padrão como rascunho inativo':modal==='history'?'Histórico global preservado':modal==='catalog'?'Editar tabela global':'Publicar padrão fiscal global'" @close="close()"><p v-if="error" class="message error" role="alert">{{error}}</p>
<template v-if="modal==='history'"><div v-for="version in versions" :key="version.version" class="panel"><h3>Versão {{version.version}} · {{version.created_by}}</h3><p v-if="version.snapshot.derived_from">Derivado de {{version.snapshot.derived_from.code}} · versão {{version.snapshot.derived_from.version}}</p><p v-if="version.snapshot.activity||version.snapshot.cnae_prefix">Atividade: {{version.snapshot.activity||'Não especificada'}} · CNAE: {{version.snapshot.cnae_prefix||'Sem filtro, confirmação manual'}}</p><p>{{version.snapshot.description||version.snapshot.name}}</p><p v-if="version.snapshot.rates_declared">Alíquotas informativas: {{version.snapshot.rates_declared.join(' · ')||'Não informadas'}}</p><ul v-if="version.snapshot.rules"><li v-for="(rule,index) in version.snapshot.rules" :key="index">{{rule.name}} · {{rule.tax}} · {{rule.rate??'Sem alíquota'}} · {{rule.cfop||'Sem filtro CFOP'}} · {{rule.ncm||'Sem filtro NCM'}}</li></ul><small>{{version.created_at}} · {{version.snapshot.source}}</small></div></template>
<form v-else-if="modal==='apply'" id="fiscal-library-apply" @submit.prevent="prepare"><fieldset :disabled="busy"><h3>{{form.name}}</h3><p v-if="form.cnae_prefix">O padrão exige CNAE principal iniciado por {{form.cnae_prefix}}. CNAE cadastrado: {{company?.cnae||'não informado'}}.</p><p v-if="form.pattern_activity&&!form.cnae_prefix">Atividade confirmada manualmente; padrão sem filtro CNAE. A estrutura não determina o enquadramento fiscal.</p><div class="form-grid"><label>Segmento confirmado da empresa *<select v-model="form.segment" required><option disabled value="">Selecione após conferir</option><option :value="form.pattern_segment">{{segmentLabels[form.pattern_segment]}}</option></select></label><label v-if="form.pattern_activity">Atividade confirmada *<select v-model="form.activity_confirmed" required><option disabled value="">Confirme após revisar</option><option :value="form.pattern_activity">{{form.pattern_activity}}</option></select></label><label>Início da vigência *<DateInput v-model="form.valid_from" required/></label><label>Fim da vigência<DateInput v-model="form.valid_to"/></label><label>Responsável pela revisão *<input v-model="form.responsible" required maxlength="200"/></label><label class="span-2">Motivo da importação *<textarea v-model="form.reason" required maxlength="1000"/></label></div></fieldset><div v-if="preview" class="message info"><div><p>{{preview.rules_to_create}} regras serão copiadas como rascunho inativo. {{preview.existing_rules.length}} regras existentes serão preservadas.</p><ul><li v-for="(rule,index) in preview.pattern.rules" :key="index">{{rule.name}} · {{rule.tax}} · {{rule.rate??'Sem alíquota'}}%</li></ul><p>Ajuste as cópias em Regras e vigência antes de conferir e ativar. Atividade/CNAE não se tornam filtros automáticos de apuração. Importar novamente o mesmo padrão/versão/intervalo não duplica regras.</p></div></div></form>
<form v-else id="fiscal-library-edit" @submit.prevent="save"><fieldset :disabled="busy"><p v-if="form.base_pattern_id||form.derived_from" class="message info">Derivação rastreável de {{form.derived_from?.code||'padrão #'+form.base_pattern_id}} · versão {{form.derived_from?.version||form.base_version}}. A origem não será alterada.</p><p class="message warning">Esta edição altera a biblioteca compartilhada. Cadastros e regras já existentes nas empresas não serão substituídos.</p><label v-if="modal==='pattern'&&!form.id&&!form.base_pattern_id">Estrutura inicial opcional<select @change="starter"><option value="">Escolher estrutura sem alíquotas</option><option v-for="row in data.starters" :key="row.code" :value="row.code">{{regimeLabels[row.regime]}} · {{segmentLabels[row.segment]}}</option></select></label>
<div class="form-grid"><label>Código *<input v-model="form.code" required :readonly="modal==='catalog'&&form.kind==='cfop'"/></label><label>{{modal==='catalog'?'Descrição':'Nome'}} *<input v-if="modal==='catalog'" v-model="form.description" required/><input v-else v-model="form.name" required/></label><label v-if="modal==='pattern'">Regime *<select v-model="form.regime" required><option v-for="(label,value) in regimeLabels" :key="value" :value="value">{{label}}</option></select></label><label v-if="modal==='pattern'">Segmento *<select v-model="form.segment" required><option disabled value="">Selecione</option><option v-for="(label,value) in segmentLabels" :key="value" :value="value">{{label}}</option></select></label><label v-if="modal==='pattern'">Atividade declarada<input v-model="form.activity" maxlength="200" placeholder="Ex.: Farmácia, sem enquadramento presumido"/></label><label v-if="modal==='pattern'">Filtro CNAE opcional<input v-model="form.cnae_prefix" maxlength="7" pattern="[0-9]{2,7}" placeholder="Prefixo de 2 a 7 dígitos"/></label><template v-if="modal==='catalog'&&form.kind==='service'"><label>Tabela do serviço *<select v-model="form.service_system"><option value="lc116">Lista LC116</option><option value="national_nfse">Tributação nacional NFS-e</option><option value="municipal">Código municipal</option></select></label><label>Jurisdição *<input v-model="form.jurisdiction" required placeholder="BR ou código IBGE municipal"/></label></template><label v-if="modal==='catalog'" class="span-2">Alíquotas informativas, separadas por ponto e vírgula<textarea v-model="form.rates_text" rows="3" placeholder="7; 12; 18,5"/></label><label v-if="modal==='catalog'">Sentido<select v-model="form.direction"><option value="both">Ambos</option><option value="incoming">Entrada</option><option value="outgoing">Saída</option></select></label><label>Início da vigência declarada<DateInput v-model="form.valid_from"/></label><label>Fim da vigência declarada<DateInput v-model="form.valid_to"/></label><label class="span-2">Fonte / fundamento *<textarea v-model="form.source" required maxlength="1500"/></label><label v-if="modal==='pattern'" class="span-2">Descrição<textarea v-model="form.description" maxlength="1500"/></label><label class="span-2">Motivo da alteração global *<textarea v-model="form.reason" required maxlength="1000"/></label><label><input v-model="form.active" type="checkbox"/>Disponível na biblioteca</label></div>
<template v-if="modal==='catalog'&&form.source_rates_declared?.length"><p>Alíquotas originais preservadas: {{form.source_rates_declared.join(' · ')}}. Não identificam incidência, tributo, UF, regime nem vigência.</p></template>
<template v-if="modal==='pattern'"><h3>Regras propostas</h3><div v-for="(rule,index) in form.rules" :key="index" class="panel fiscal-rule"><div class="form-grid"><label>Nome *<input v-model="rule.name" required/></label><label>Tributo *<select v-model="rule.tax"><option v-for="tax in ['icms','ipi','iss','pis','cofins','ibs','cbs']" :key="tax" :value="tax">{{tax.toUpperCase()}}</option></select></label><label>Alíquota proposta<input v-model="rule.rate" inputmode="decimal" placeholder="Sem alíquota"/></label><label>Sentido<select v-model="rule.direction"><option value="both">Ambos</option><option value="incoming">Entrada</option><option value="outgoing">Saída</option></select></label><label>CFOP<input v-model="rule.cfop" pattern="[0-9]{4}"/></label><label>NCM<input v-model="rule.ncm" pattern="[0-9]{8}"/></label><label>UF<input v-model="rule.state" maxlength="2"/></label><label>Município IBGE<input v-model="rule.municipality" pattern="[0-9]{7}"/></label><label class="span-2">Fundamento específico<input v-model="rule.source" maxlength="1500"/></label></div><button class="text-button" type="button" :disabled="form.rules.length===1" @click="form.rules.splice(index,1)">Remover regra</button></div><button class="button" type="button" :disabled="form.rules.length>=200" @click="form.rules.push(blankRule())">Adicionar regra</button></template>
</fieldset></form><template #footer><button class="button" :disabled="busy" @click="close()">{{modal==='history'?'Fechar':'Cancelar'}}</button><button v-if="modal==='catalog'||modal==='pattern'" class="button primary" type="submit" form="fiscal-library-edit" :disabled="busy">Salvar global</button><template v-if="modal==='apply'"><button class="button" type="submit" form="fiscal-library-apply" :disabled="busy">Conferir prévia</button><button class="button primary" :disabled="busy||!preview" @click="apply">Confirmar importação inativa</button></template></template></BaseModal>
</details></template>
<style scoped>
.fiscal-library{padding:16px;margin:12px 0}.fiscal-library summary{cursor:pointer;font-weight:600}.fiscal-library small{display:block;color:var(--text-muted)}.fiscal-library td{max-width:420px;overflow-wrap:anywhere}.fiscal-library fieldset{border:0;margin:0;padding:0}.fiscal-rule{padding:12px;margin-bottom:12px}.fiscal-library .message{margin:12px 0}.fiscal-library .table-toolbar{gap:8px;flex-wrap:wrap}
</style>
